INSERT INTO "public"."monitoring_evaluation_indicator" ("UUID", "isDeleted", "Json_ext", "DateCreated", "DateUpdated", "version", "DateValidFrom", "DateValidTo", "ReplacementUUID", "code", "name", "description", "unit", "frequency", "module", "formula", "is_automatic", "is_active", "created_by_id", "updated_by_id", "UserCreatedUUID", "UserUpdatedUUID", "target", "method", "status", "calculation_method", "type", "category") VALUES ('a1c24073-709e-4c0e-89da-7f1b2c451a34', false, NULL, '2025-12-15 11:21:20.085032+00', '2025-12-17 14:51:21.023506+00', 2, '2025-12-15 11:21:20.084664+00', NULL, NULL, 'IRI.012', 'Pourcentage de plaintes reçues traitées dans les délais par le mécanisme de règlement des plaintes du Projet ', ' Cet indicateur mesurera la performance du système de MGP, qui sera continuellement amélioré tout au long de la durée du projet. Cet indicateur mesurera la rapidité des réponses aux griefs formels reçus par le projet.                                                                                  ', 'Pourcentage', 'Trimestriel', 'grievance_social_protection', 'IRI_012', false, true, NULL, NULL, '0a0759cd-9966-444a-b767-132c3b2f72e8', '0a0759cd-9966-444a-b767-132c3b2f72e8', 80, 'AUTOMATIQUE', 'ACTIVE', 'Nbre de plaintes reçues et traitées dans les délais requis ÷ Nbre total de plaintes reçues X 100 ', 'QUANTITATIVE', 'RESULT_FRAMEWORK');
